CREATE ROLE mandate_app NOLOGIN;
CREATE FUNCTION tenant_id() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('mandate.organisation',true),'') $$;
CREATE TABLE organisations (id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id text PRIMARY KEY, organisation_id text NOT NULL REFERENCES organisations, auth_id text UNIQUE, name text NOT NULL, email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organisation_id,id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE capital_providers (id text NOT NULL, organisation_id text NOT NULL REFERENCES organisations, name text NOT NULL, data jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(organisation_id,id));
CREATE TABLE provider_mandates (id text NOT NULL, organisation_id text NOT NULL, provider_id text NOT NULL, effective_from timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), data jsonb NOT NULL, PRIMARY KEY(organisation_id,id), FOREIGN KEY(organisation_id,provider_id) REFERENCES capital_providers(organisation_id,id));
CREATE TABLE deals (id text PRIMARY KEY, organisation_id text NOT NULL REFERENCES organisations, created_by_user_id text NOT NULL, assigned_user_id text NOT NULL, deal_name text NOT NULL, overall_stage text NOT NULL DEFAULT 'draft' CHECK(overall_stage IN ('draft','adviser_review','ready_to_send','sent_to_lender','more_information_needed','terms_review','due_diligence','documentation','funded','closed','withdrawn','archived','decision_received')), profile jsonb NOT NULL, profile_version integer NOT NULL DEFAULT 1, confirmed_version integer, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organisation_id,id), FOREIGN KEY(organisation_id,assigned_user_id) REFERENCES users(organisation_id,id), FOREIGN KEY(organisation_id,created_by_user_id) REFERENCES users(organisation_id,id));
CREATE TABLE profile_versions (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, version integer NOT NULL, profile jsonb NOT NULL, actor_user_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organisation_id,deal_id,version), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id));
CREATE TABLE documents (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, filename text NOT NULL, content text NOT NULL, facts jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id));
CREATE TABLE matching_runs (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, profile_version integer NOT NULL, snapshot jsonb NOT NULL, engine_version text NOT NULL, saved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organisation_id,id), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id));
CREATE TABLE match_results (id text PRIMARY KEY, organisation_id text NOT NULL, run_id text NOT NULL, provider_id text NOT NULL, mandate_id text NOT NULL, result jsonb NOT NULL, UNIQUE(organisation_id,run_id,provider_id), FOREIGN KEY(organisation_id,run_id) REFERENCES matching_runs(organisation_id,id), FOREIGN KEY(organisation_id,provider_id) REFERENCES capital_providers(organisation_id,id), FOREIGN KEY(organisation_id,mandate_id) REFERENCES provider_mandates(organisation_id,id));
CREATE TABLE deal_matches (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, provider_id text NOT NULL, original_result_id text REFERENCES match_results, latest_result_id text REFERENCES match_results, status text NOT NULL DEFAULT 'NOT_CONTACTED' CHECK(status IN ('NOT_CONTACTED','CONTACTED','WAITING','INTERESTED','TERMS_RECEIVED','DECLINED','CLOSED','WITHDRAWN')), selection text NOT NULL DEFAULT 'considering' CHECK(selection IN ('considering','shortlisted','dismissed')), decline_reason text CHECK(decline_reason IN ('DEAL_TOO_SMALL','DEAL_TOO_LARGE','WRONG_SECTOR','LEVERAGE_TOO_HIGH','RETURN_TOO_LOW','SECURITY_UNSUITABLE','TERM_UNSUITABLE','NO_CAPITAL_AVAILABLE','TIMING','OTHER')), last_contacted_at timestamptz, next_follow_up_at timestamptz, follow_up_note text, assigned_user_id text NOT NULL, version integer NOT NULL DEFAULT 1, matched_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organisation_id,deal_id,provider_id), UNIQUE(organisation_id,id), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id), FOREIGN KEY(organisation_id,provider_id) REFERENCES capital_providers(organisation_id,id), FOREIGN KEY(organisation_id,assigned_user_id) REFERENCES users(organisation_id,id));
CREATE TABLE deal_events (sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE, id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, deal_match_id text, provider_id text, actor_user_id text NOT NULL, event_type text NOT NULL, previous_status text, new_status text, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id), FOREIGN KEY(organisation_id,deal_match_id) REFERENCES deal_matches(organisation_id,id), FOREIGN KEY(organisation_id,actor_user_id) REFERENCES users(organisation_id,id));
CREATE TABLE deal_notes (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, deal_match_id text, user_id text NOT NULL, note_text text NOT NULL CHECK(length(note_text) BETWEEN 1 AND 10000), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id), FOREIGN KEY(organisation_id,deal_match_id) REFERENCES deal_matches(organisation_id,id), FOREIGN KEY(organisation_id,user_id) REFERENCES users(organisation_id,id));
CREATE TABLE packages (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, run_id text NOT NULL, profile_version integer NOT NULL, name text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id), FOREIGN KEY(organisation_id,run_id) REFERENCES matching_runs(organisation_id,id));
CREATE TABLE funding_records (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, deal_match_id text NOT NULL, facility_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('indication','terms','commitment','funding')), amount_cents bigint NOT NULL CHECK(amount_cents >= 0), state text NOT NULL CHECK(state IN ('indicative','conditional','active','withdrawn','funded')), expires_at timestamptz, supersedes_id text REFERENCES funding_records, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id), FOREIGN KEY(organisation_id,deal_match_id) REFERENCES deal_matches(organisation_id,id));
CREATE TABLE tasks (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, title text NOT NULL, assigned_user_id text NOT NULL, due_at timestamptz, completed boolean NOT NULL DEFAULT false, evidence text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id), FOREIGN KEY(organisation_id,assigned_user_id) REFERENCES users(organisation_id,id));
CREATE TABLE reports (id text PRIMARY KEY, organisation_id text NOT NULL, deal_id text NOT NULL, provider_id text NOT NULL, audience text NOT NULL CHECK(audience IN ('internal','shareable')), snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id));
CREATE TABLE source_records (id text NOT NULL, organisation_id text NOT NULL, deal_id text NOT NULL, kind text NOT NULL, data jsonb NOT NULL, PRIMARY KEY(organisation_id,deal_id,kind,id), FOREIGN KEY(organisation_id,deal_id) REFERENCES deals(organisation_id,id));
CREATE TABLE requests (organisation_id text NOT NULL, key text NOT NULL, fingerprint text NOT NULL, response jsonb NOT NULL, PRIMARY KEY(organisation_id,key));
CREATE FUNCTION forbid_history_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END $$;
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['users','capital_providers','provider_mandates','deals','profile_versions','documents','matching_runs','match_results','deal_matches','deal_events','deal_notes','packages','funding_records','tasks','reports','source_records','requests'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY tenant_boundary ON %I TO mandate_app USING (organisation_id = tenant_id()) WITH CHECK (organisation_id = tenant_id())',t);
  EXECUTE format('GRANT SELECT, INSERT, UPDATE ON %I TO mandate_app',t);
  EXECUTE format('CREATE INDEX ON %I (organisation_id)',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['provider_mandates','profile_versions','match_results','deal_events','deal_notes','packages','funding_records','reports','source_records','requests'] LOOP
  EXECUTE format('REVOKE UPDATE, DELETE ON %I FROM mandate_app',t);
  EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION forbid_history_change()',t);
 END LOOP;
END $$;
GRANT USAGE ON SEQUENCE deal_events_sequence_seq TO mandate_app;
GRANT SELECT ON organisations TO mandate_app;
ALTER TABLE organisations ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_organisation ON organisations TO mandate_app USING(id=tenant_id());
CREATE INDEX ON deals(organisation_id,overall_stage,assigned_user_id);
CREATE INDEX ON deal_matches(organisation_id,provider_id,status);
CREATE INDEX ON deal_matches(organisation_id,deal_id,next_follow_up_at);
CREATE INDEX ON deal_events(organisation_id,deal_id,occurred_at DESC,sequence DESC);
CREATE INDEX ON provider_mandates(organisation_id,provider_id,effective_from DESC);
